class EscrowModule {
    constructor(provider, wallet) {
        this.provider = provider;
        this.wallet = wallet;
    }
    async getUserBalance(token, walletAddress, isOperator = false) {
        try {
            const contractAbi = EscrowAbi;
            const contractAddress = EscrowTestnet;
            const contract = new ethers.Contract(contractAddress, contractAbi, this.provider);
            const tokenDetails = tokenMap[networkType].find((eachToken) => eachToken.symbol.toLowerCase() === token.toLowerCase());
            if (!tokenDetails) {
                throw new Error('Provided token symbol is invalid.');
            }
            const tokenAddress = tokenDetails?.address || '0x0000000000000000000000000000000000000000';
            let userWalletAddress;
            if (walletAddress) {
                userWalletAddress = walletAddress;
            }
            else {
                if (this.wallet) {
                    userWalletAddress = await this.wallet.getAddress();
                }
                else {
                    throw new Error('No wallet address provided');
                }
            }
            const response = await contract.getUserData(userWalletAddress, tokenAddress, isOperator);
            const userData = {
                lockedBalance: response[0].toString(),
                unlockedBalance: response[1].toString(),
                token: {
                    name: tokenDetails?.name,
                    symbol: tokenDetails?.symbol,
                    decimal: tokenDetails?.decimal,
                },
            };
            return userData;
        }
        catch (error) {
            const errorMessage = handleContractError(error, EscrowAbi);
            throw errorMessage;
        }
    }
    // write operations
    async depositBalance({ token, amount, onSuccessCallback, onFailureCallback }) {
        try {
            const { signer } = await initializeSigner({ wallet: this.wallet });
            const contractABI = EscrowAbi;
            const contractAddress = EscrowTestnet;
            const tokenABI = TokenAbi;
            const tokenDetails = tokenMap[networkType].find((eachToken) => eachToken.symbol.toLowerCase() === token.toLowerCase());
            if (!tokenDetails) {
                throw new Error('Provided token symbol is invalid.');
            }
            const decimals = tokenDetails?.decimal ?? 18;
            const tokenAddress = tokenDetails?.address;
            const contract = new ethers.Contract(contractAddress, contractABI, signer);
            const tokenContract = new ethers.Contract(tokenAddress, tokenABI, signer);
            const finalAmount = Number(amount.toString());
            const depositAmount = ethers.parseUnits(finalAmount.toFixed(decimals), decimals);
            const approvalTxn = await tokenContract.approve(contractAddress, depositAmount);
            await approvalTxn.wait();
            const result = await contract.deposit(tokenAddress, depositAmount);
            const receipt = await result.wait();
            if (onSuccessCallback)
                onSuccessCallback(receipt);
            return receipt;
        }
        catch (error) {
            if (onFailureCallback)
                onFailureCallback(error);
            const errorMessage = handleContractError(error, EscrowAbi);
            throw errorMessage;
        }
    }
    async withdrawBalance({ token, amount, onSuccessCallback, onFailureCallback }) {
        try {
            const { signer } = await initializeSigner({ wallet: this.wallet });
            const contractABI = EscrowAbi;
            const contractAddress = EscrowTestnet;
            const tokenDetails = tokenMap[networkType].find((eachToken) => eachToken.symbol.toLowerCase() === token.toLowerCase());
            if (!tokenDetails) {
                throw new Error('Provided token symbol is invalid.');
            }
            const decimals = tokenDetails?.decimal ?? 18;
            const tokenAddress = tokenDetails?.address;
            const contract = new ethers.Contract(contractAddress, contractABI, signer);
            const finalAmount = (Number(amount.toString()) * 10 ** decimals - 1) / 10 ** decimals;
            const withdrawAmount = ethers.parseUnits(finalAmount.toFixed(decimals), decimals);
            const result = await contract.withdraw(tokenAddress, withdrawAmount);
            const receipt = await result.wait();
            if (onSuccessCallback)
                onSuccessCallback(receipt);
            return receipt;
        }
        catch (error) {
            if (onFailureCallback)
                onFailureCallback(error);
            const errorMessage = handleContractError(error, EscrowAbi);
            throw errorMessage;
        }
    }
    async withdrawProviderEarnings({ rewardWallet, tokenAddress, amount, decimals, onSuccessCallback, onFailureCallback, }) {
        try {
            const { signer } = await initializeSigner({ wallet: this.wallet });
            const contractABI = EscrowAbi;
            const contractAddress = EscrowTestnet;
            const contract = new ethers.Contract(contractAddress, contractABI, signer);
            const finalAmount = (Number(amount.toString()) - 1) / 10 ** decimals;
            const withdrawAmount = ethers.parseUnits(finalAmount.toFixed(decimals), decimals);
            const result = await contract.withdrawProviderEarnings(rewardWallet, tokenAddress, withdrawAmount);
            const receipt = await result.wait();
            if (onSuccessCallback)
                onSuccessCallback(receipt);
            return receipt;
        }
        catch (error) {
            if (onFailureCallback)
                onFailureCallback(error);
            const errorMessage = handleContractError(error, EscrowAbi);
            throw errorMessage;
        }
    }
    async withdrawFizzEarnings({ rewardWallet, tokenAddress, amount, decimals, onSuccessCallback, onFailureCallback, }) {
        try {
            const { signer } = await initializeSigner({ wallet: this.wallet });
            const contractABI = EscrowAbi;
            const contractAddress = EscrowTestnet;
            const contract = new ethers.Contract(contractAddress, contractABI, signer);
            const finalAmount = (Number(amount.toString()) - 1) / 10 ** decimals;
            const withdrawAmount = ethers.parseUnits(finalAmount.toFixed(decimals), decimals);
            const result = await contract.withdrawFizzNodeEarnings(rewardWallet, tokenAddress, withdrawAmount);
            const receipt = await result.wait();
            if (onSuccessCallback)
                onSuccessCallback(receipt);
            return receipt;
        }
        catch (error) {
            if (onFailureCallback)
                onFailureCallback(error);
            const errorMessage = handleContractError(error, EscrowAbi);
            throw errorMessage;
        }
    }
    // read operations
    async getProviderEarnings(providerAddress, tokenAddress) {
        try {
            const contractAbi = EscrowAbi;
            const contractAddress = EscrowTestnet;
            const contract = new ethers.Contract(contractAddress, contractAbi, this.provider);
            const response = await contract.getProviderEarnings(providerAddress, tokenAddress);
            const providerEarnings = {
                earned: response[0].toString(),
                withdrawn: response[1].toString(),
                balance: response[2].toString(),
            };
            return providerEarnings;
        }
        catch (error) {
            const errorMessage = handleContractError(error, EscrowAbi);
            throw errorMessage;
        }
    }
    async getFizzEarnings(fizzAddress, tokenAddress) {
        try {
            const contractAbi = EscrowAbi;
            const contractAddress = EscrowTestnet;
            const contract = new ethers.Contract(contractAddress, contractAbi, this.provider);
            const response = await contract.getFizzNodeEarnings(fizzAddress, tokenAddress);
            const fizzEarnings = {
                earned: response[0].toString(),
                withdrawn: response[1].toString(),
                balance: response[2].toString(),
            };
            return fizzEarnings;
        }
        catch (error) {
            const errorMessage = handleContractError(error, EscrowAbi);
            throw errorMessage;
        }
    }
}

class SpheronProviderModule {
    constructor(providerHostUrl, proxyUrl) {
        this.providerHostUrl = providerHostUrl;
        this.proxyUrl = proxyUrl;
    }
    async closeDeployment(certificate, authToken) {
        const url = `${this.proxyUrl}`;
        try {
            const response = await requestPipeline({
                url,
                method: 'POST',
                body: JSON.stringify({
                    certificate,
                    authToken,
                    url: `${this.providerHostUrl}/spheron/deployment/close`,
                    method: 'PUT',
                }),
            });
            return response;
        }
        catch (error) {
            throw error;
        }
    }
    async version() {
        const url = `${this.proxyUrl}`;
        try {
            const response = await requestPipeline({
                url,
                method: 'POST',
                body: JSON.stringify({
                    url: `${this.providerHostUrl}/version`,
                }),
            });
            return response;
        }
        catch (error) {
            throw error;
        }
    }
    async submitManfiest(certificate, authToken, leaseId, sdlManifest) {
        // if (!certificate) {
        //   console.log('Certificate not found');
        //   return;
        // }
        const url = `${this.proxyUrl}`;
        try {
            const reqBody = {
                certificate,
                authToken,
                method: 'PUT',
                url: `${this.providerHostUrl}/deployment/${leaseId}/manifest`,
                body: JSON.stringify(sdlManifest),
            };
            const response = await requestPipeline({
                url,
                method: 'POST',
                body: JSON.stringify(reqBody),
            });
            return response;
        }
        catch (error) {
            throw error;
        }
    }
    async getLeaseStatus(certificate, authToken, leaseId) {
        if (!leaseId) {
            throw new Error('Lease ID not found');
        }
        const reqBody = {
            certificate,
            authToken,
            method: 'GET',
            url: `${this.providerHostUrl}/lease/${leaseId}/${GSEQ}/${OSEQ}/status`,
        };
        const url = `${this.proxyUrl}`;
        try {
            const response = await requestPipeline({
                url,
                method: 'POST',
                body: JSON.stringify(reqBody),
            });
            return response;
        }
        catch (error) {
            return { services: null, forwarded_ports: null };
        }
    }
    async getKubeEvents(certificate, authToken, leaseId, service = '', tail = 100000) {
        if (!leaseId) {
            throw new Error('Lease ID not found');
        }
        const reqBody = {
            // eslint-disable-next-line prettier/prettier
            url: `${this.providerHostUrl}/lease/${leaseId}/${GSEQ}/${OSEQ}/kubeevents?follow=false&tail=${tail}${service ? `&service=${service}` : ''}`,
            method: 'GET',
            authToken,
            certificate,
        };
        const url = `${this.proxyUrl}`;
        try {
            const response = await requestPipeline({
                method: 'POST',
                body: JSON.stringify(reqBody),
                url,
            });
            return response;
        }
        catch (error) {
            throw error;
        }
    }
    async getLeaseLogs(certificate, authToken, leaseId, service = '', tail = 100000, startup = false) {
        if (!leaseId) {
            throw new Error('Lease ID not found');
        }
        const reqBody = {
            // eslint-disable-next-line prettier/prettier
            url: `${this.providerHostUrl}/lease/${leaseId}/${GSEQ}/${OSEQ}/logs?follow=false&tail=${tail}&startup=${startup}${service ? `&service=${service}` : ''}`,
            method: 'GET',
            authToken,
            certificate,
        };
        const url = `${this.proxyUrl}`;
        try {
            const response = await requestPipeline({
                url,
                method: 'POST',
                body: JSON.stringify(reqBody),
            });
            return response;
        }
        catch (error) {
            return [];
        }
    }
    async getLeaseServiceStatus(certificate, authToken, leaseId, serviceName) {
        if (!leaseId) {
            throw new Error('Lease ID not found');
        }
        if (!serviceName) {
            throw new Error('Service name not found');
        }
        const reqBody = {
            url: `${this.providerHostUrl}/lease/${leaseId}/${GSEQ}/${OSEQ}/service/${serviceName}/status`,
            method: 'GET',
            authToken,
            certificate,
        };
        const url = `${this.proxyUrl}`;
        try {
            const response = await requestPipeline({
                url,
                method: 'POST',
                body: JSON.stringify(reqBody),
            });
            return response;
        }
        catch (error) {
            throw error;
        }
    }
    async leaseShell(certificate, authToken, leaseId) {
        if (!leaseId) {
            throw new Error('Lease ID not found');
        }
        const reqBody = {
            url: `${this.providerHostUrl}/lease/${leaseId}/${GSEQ}/${OSEQ}/shell`,
            method: 'POST',
            certificate,
            authToken,
        };
        const url = `${this.proxyUrl}`;
        try {
            const response = await requestPipeline({
                url,
                method: 'POST',
                body: JSON.stringify(reqBody),
            });
            return response;
        }
        catch (error) {
            throw error;
        }
    }
    async closeDeploymentAndLease(certificate, authToken, provider, leaseId) {
        try {
            const lease = new LeaseModule(provider);
            const leaseResponse = await lease.closeLease(leaseId);
            const closeDeployment = await this.closeDeployment(certificate, authToken);
            return { lease: leaseResponse, closeDeployment };
        }
        catch (error) {
            throw error;
        }
    }
}

